// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 balance, uint256 value) public {
        vm.assume(value > 0);
        vm.assume(balance > 0);
        vm.assume(value > balance);
        vm.deal(address(c), balance);

        address owner = address(this);
        vm.prank(owner);
        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }

        // Rule: withdrawing more than the contract holds must revert;
        // the mutated empty withdraw(v) succeeds instead.
        assertTrue(value > address(c).balance && !ok);
    }
}
